package com.bank.qa.parallel;

// Models how wall-clock time and error rate change with worker count,
// given finite environment capacity (the bottleneck).
class EnvModel {
    private final int totalTests;
    private final double perTestSeconds;   // ideal time per test
    private final int envCapacity;         // concurrent requests env sustains
    private final int machineCores;        // CPU ceiling on the runner

    EnvModel(int totalTests, double perTestSeconds, int envCapacity, int machineCores) {
        this.totalTests = totalTests; this.perTestSeconds = perTestSeconds;
        this.envCapacity = envCapacity; this.machineCores = machineCores;
    }

    // Effective parallelism is capped by the SMALLEST constraint.
    int effectiveParallelism(int workers) {
        return Math.min(workers, Math.min(envCapacity, machineCores));
    }

    // Wall-clock time: improves with effective parallelism; beyond the
    // bottleneck, extra workers add contention overhead instead of speed.
    double wallClockSeconds(int workers) {
        int eff = effectiveParallelism(workers);
        double base = (totalTests * perTestSeconds) / eff;
        int overSubscription = Math.max(0, workers - Math.min(envCapacity, machineCores));
        double contentionPenalty = base * 0.08 * overSubscription; // grows past bottleneck
        return base + contentionPenalty;
    }

    // Error rate: ~0 while within capacity, rises once oversubscribed.
    double errorRatePct(int workers) {
        int over = Math.max(0, workers - envCapacity);
        return Math.min(40.0, over * 5.0); // timeouts/flakiness climb past capacity
    }
}
