package com.bank.qa.parallel;

import java.util.logging.*;

public class ParallelismDemo {
    private static final Logger log = Logger.getLogger(ParallelismDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ParLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // 200 tests, 2s each, env sustains ~6 concurrent, runner has 8 cores.
        EnvModel env = new EnvModel(200, 2.0, 6, 8);

        log.info("=== Sweeping worker count (bottleneck = env capacity 6) ===");
        double best = Double.MAX_VALUE; int bestWorkers = 1;
        for (int workers = 1; workers <= 16; workers++) {
            double time = env.wallClockSeconds(workers);
            double err = env.errorRatePct(workers);
            if (time < best && err < 1.0) { best = time; bestWorkers = workers; }
            String note = (err >= 1.0) ? "  <-- oversubscribed: contention + flakiness" : "";
            log.info(String.format("workers=%2d  time=%6.1fs  errorRate=%4.1f%%%s",
                workers, time, err, note));
        }
        log.info("Optimal worker count ~ " + bestWorkers
            + " (matches env capacity; beyond it, more workers HURT time & reliability)");
    }
}

// ─── Would be in ParLogFormatter.java in a real project ───
class ParLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
